def tidy(x,key=''):
 if isinstance(x,dict):return {k:tidy(v,k) for k,v in x.items()}
 if isinstance(x,list):return [tidy(v,key) for v in x]
 if isinstance(x,str) and key in prose_keys:
  x=re.sub(r'([A-Za-z])([0-9])',r'\1 \2',x)
  x=re.sub(r'([0-9])([A-Za-z])',r'\1 \2',x)
  x=re.sub(r',(?=[A-Za-z])',', ',x)
  x=x.replace('I 00742','I00742').replace('1 st','1st').replace('plusNational','plus National').replace('inAmpara','in Ampara').replace('andMoraLs','and MoraLs')
 return x
